## 3. Result-Generation Logic (form data → recommendation)

Logic is defined inline in the Compass page (no separate lib file).

Source: `client/src/pages/RLSPLMDCompass.tsx`

```typescript
interface RLSInputs {
  irlss_score: string;
  plmi: string;
  plm_diagnosis: boolean;
  rls_diagnosis: boolean;
  duration_years: string;
  ferritin: string;
  transferrin_sat: string;
  iron_infusion_tried: boolean;
  prior_gabapentin: boolean;
  prior_pregabalin: boolean;
  prior_gabapentin_enacarbil: boolean;
  prior_pramipexole: boolean;
  prior_ropinirole: boolean;
  augmentation: boolean;
  renal_impairment: boolean;
  egfr: string;
  pregnancy: boolean;
  comorbid_depression: boolean;
  comorbid_anxiety: boolean;
  severity: "mild" | "moderate" | "severe" | "unknown";
}

const defaultInputs: RLSInputs = {
  irlss_score: "",
  plmi: "",
  plm_diagnosis: false,
  rls_diagnosis: false,
  duration_years: "",
  ferritin: "",
  transferrin_sat: "",
  iron_infusion_tried: false,
  prior_gabapentin: false,
  prior_pregabalin: false,
  prior_gabapentin_enacarbil: false,
  prior_pramipexole: false,
  prior_ropinirole: false,
  augmentation: false,
  renal_impairment: false,
  egfr: "",
  pregnancy: false,
  comorbid_depression: false,
  comorbid_anxiety: false,
  severity: "unknown",
};

function evaluate(inputs: RLSInputs) {
  const irlss = parseInt(inputs.irlss_score);
  const ferritin = parseFloat(inputs.ferritin);
  const egfr = parseFloat(inputs.egfr);

  const severity = irlss >= 31 ? "severe" : irlss >= 21 ? "moderate-severe" : irlss >= 11 ? "moderate" : irlss >= 1 ? "mild" : inputs.severity;
  const ironDeficient = ferritin < 75 || (ferritin < 100 && parseFloat(inputs.transferrin_sat) < 20);

  const recommendations: string[] = [];
  const contraindications: string[] = [];
  const notes: string[] = [];

  // AASM 2024 RLS/PLMD CPG
  // Iron first
  if (ironDeficient) {
    if (!inputs.iron_infusion_tried) {
      recommendations.push("IV Ferric Carboxymaltose (Injectafer): STRONGLY RECOMMENDED for RLS with serum ferritin <75 ng/mL or ferritin <100 with transferrin sat <20% — AASM 2024 CPG");
      recommendations.push("Target serum ferritin ≥75 ng/mL (ideally ≥100 ng/mL) before initiating pharmacotherapy");
    } else {
      notes.push("IV iron infusion previously attempted — reassess ferritin response before escalating pharmacotherapy");
    }
  }

  // Alpha-2-delta ligands — STRONGLY RECOMMENDED
  if (!inputs.prior_gabapentin_enacarbil) {
    recommendations.push("Gabapentin Enacarbil (Horizant): STRONGLY RECOMMENDED — AASM 2024 CPG. Preferred alpha-2-delta ligand for RLS; extended-release formulation with consistent bioavailability");
  }
  if (!inputs.prior_pregabalin) {
    recommendations.push("Pregabalin (Lyrica): STRONGLY RECOMMENDED — AASM 2024 CPG. Effective for RLS and comorbid anxiety/pain");
  }
  if (!inputs.prior_gabapentin) {
    recommendations.push("Gabapentin (Neurontin): STRONGLY RECOMMENDED — AASM 2024 CPG. Dose 300–1800 mg QHS; adjust for renal function");
  }

  // Dopamine agonists — CONDITIONALLY AGAINST
  if (inputs.prior_pramipexole || inputs.prior_ropinirole) {
    if (inputs.augmentation) {
      contraindications.push("⚠️ AUGMENTATION DOCUMENTED: Dopamine agonists (pramipexole, ropinirole) are CONDITIONALLY RECOMMENDED AGAINST as first-line therapy per AASM 2024 CPG due to augmentation risk. Taper and transition to alpha-2-delta ligand.");
    } else {
      notes.push("Dopamine agonists (pramipexole, ropinirole) are now CONDITIONALLY RECOMMENDED AGAINST as first-line therapy per AASM 2024 CPG due to augmentation risk (symptoms worsen over time, spread to arms, occur earlier in day). Monitor for augmentation using IRLSS trends.");
    }
  } else {
    notes.push("AASM 2024 CPG Update: Dopamine agonists (pramipexole, ropinirole) are now CONDITIONALLY RECOMMENDED AGAINST as first-line therapy due to augmentation risk. Prefer alpha-2-delta ligands as first-line pharmacotherapy.");
  }

  // Renal adjustment
  if (inputs.renal_impairment || egfr < 60) {
    notes.push(`Renal impairment (eGFR: ${inputs.egfr || "reduced"}): Dose-adjust gabapentin and pregabalin. Gabapentin enacarbil is contraindicated in CrCl <30 mL/min. Consider low-dose oxycodone CR or methadone for severe refractory RLS in renal failure.`);
  }

  // Pregnancy
  if (inputs.pregnancy) {
    recommendations.push("Pregnancy: Avoid pharmacotherapy in first trimester. IV iron supplementation preferred. Low-dose clonazepam or opioids (with obstetric guidance) for severe refractory RLS in second/third trimester.");
    notes.push("All RLS medications carry pregnancy risks — consult MFM/obstetrics before initiating.");
  }

  // PLMD
  if (inputs.plm_diagnosis && parseFloat(inputs.plmi) >= 15) {
    recommendations.push(`PLMD (PLMI: ${inputs.plmi} events/hour): Alpha-2-delta ligands (gabapentin, pregabalin) are preferred. Clonazepam 0.5–2 mg QHS: CONDITIONALLY RECOMMENDED for PLMD — AASM 2024 CPG.`);
  }

  const keyFindings: string[] = [];
  if (irlss) keyFindings.push(`IRLSS Score: ${irlss}/40 — ${severity} RLS`);
  if (inputs.plmi) keyFindings.push(`PLMI: ${inputs.plmi} events/hour${parseFloat(inputs.plmi) >= 15 ? " — PLMD diagnosis criteria met" : ""}`);
  if (ironDeficient) keyFindings.push(`Iron deficiency: Ferritin ${inputs.ferritin || "?"} ng/mL — IV iron strongly recommended`);
  if (inputs.augmentation) keyFindings.push("⚠️ Augmentation documented — dopamine agonist taper indicated");

  const authRequired = true;
  const appealStrength: "strong" | "moderate" | "weak" = (inputs.rls_diagnosis && irlss >= 11) ? "strong" : "moderate";

  return { severity, recommendations, contraindications, notes, keyFindings, authRequired, appealStrength, ironDeficient };
}
